ranges.text:
// Permission for one complete, aligned 4 KiB copy in a sufficiently large
// data buffer. Samples accepted frontend jobs and retired backend jobs only;
// it never changes either handshake. The register frontend serializes jobs.
// Unexpected overlap/retirement revokes this new permission until reset.

assign eligible = CapacityBytes >= 4096 && normal_copy_i &&
                  length_i == 64'd4096 && src_i[11:0] == 0 && dst_i[11:0] == 0;
assign permit_o = pending_q && eligible_q && !fault_q && normal_copy_i;

case ({job_fire_i, job_done_i})
    2'b10: begin
        if (pending_q) fault_q <= 1'b1;
        pending_q <= 1'b1;
        eligible_q <= eligible;
    end
    2'b01: begin
        if (!pending_q) fault_q <= 1'b1;
        pending_q <= 1'b0;
        eligible_q <= 1'b0;
    end
    2'b11: begin
        // Replace a completed sole job; an immediately completed
        // job with no predecessor needs no read permission.
        pending_q <= pending_q;
        eligible_q <= pending_q && eligible;
    end

// Covers software jobs, queued backend work and a same-cycle launch read.
assign job_quiet_o = state_q == IDLE && backend_idle_i && !valid_o &&
                     !issue && !dma_reg2hw.next_id.re;
assign locked_write = batch_active_o && dma_ctrl_req_i.valid &&
                      dma_ctrl_req_i.write && !batch_access && !observer_access && !launcher_access;
assign batch_cfg_ok = !batch_error_q && batch_target_q != 0 && batch_target_q <= 33'h100000000 &&
                      batch_pages_q != 0 && batch_pages_q <= 4096 &&
                      dma_reg2hw.num_bytes.q == 4096 &&
                      dma_reg2hw.conf.ttype.q == idma_pkg::DEFAULT &&
                      dma_reg2hw.src_addr.q[11:0] == 0 && dma_reg2hw.dst_addr.q[11:0] == 0;
assign batch_task_issue = batch_active_o && state_q == COUNT && ready_i;
assign batch_task_done = batch_active_o && state_q == WAIT && trans_complete_i;

// Controlled-launch helpers
assign launch_busy = LaunchPort && launch_ctrl_q;
assign launch_next_id_read = LaunchPort && dma_ctrl_req_i.valid && !dma_ctrl_req_i.write &&
                             (full_addr == NextIdOffset);
assign launch_base_write = LaunchPort && dma_ctrl_req_i.valid && dma_ctrl_req_i.write &&
                           !batch_access && !observer_access && !launcher_access;
assign launch_locked_write = launch_busy && launch_base_write;

// Same-cycle STOP pulse for the GAP state.  This lets STOP win over a
// countdown-expiry edge in the same cycle as the 0x88 write.
assign batch_stop_write = batch_access && dma_ctrl_req_i.write && !launch_busy &&
                          dma_ctrl_req_i.wstrb == 8'hff &&
                          (full_addr == 8'h88) && (dma_ctrl_req_i.wdata == 2);

// Exactly 64-byte, DEFAULT, aligned, batch-disabled, idle-backend transfer with
// an all-zero configuration. CONF is compared per reg_pkg field to avoid packed
// aggregate comparison ambiguities.
assign launch_cfg_ok = (dma_reg2hw.conf.ttype.q     == idma_pkg::DEFAULT) &&
                       (dma_reg2hw.conf.pv.q         == 1'b0) &&
                       (dma_reg2hw.conf.cache.q      == 4'b0) &&
                       (dma_reg2hw.conf.decouple.q   == 1'b0) &&
                       (dma_reg2hw.conf.deburst.q    == 1'b0) &&
                       (dma_reg2hw.conf.serialize.q  == 1'b0) &&
                       (dma_reg2hw.num_bytes.q       == 64'd64) &&
                       (dma_reg2hw.src_addr.q[5:0]   == '0) &&
                       (dma_reg2hw.dst_addr.q[5:0]   == '0) &&
                       !batch_enable_q &&
                       backend_idle_i;

assign obs_issue_o = batch_enable_q ? batch_task_issue :
                     (LaunchPort && (launch_ctrl_q || launch_hold_i)) ?
                        (launch_ctrl_q && state_q == COUNT && ready_i) : issue;
assign obs_issue_id_o = batch_enable_q ? 64'(batch_issued_q) + 1 :
                        (LaunchPort && (launch_ctrl_q || launch_hold_i)) ?
                           (launch_ctrl_q ? launch_id_q : next_id) : next_id;
assign obs_done_o = batch_enable_q ? batch_task_done : trans_complete;
// For a controlled job report the reserved ID; otherwise keep the raw generator
// behaviour (previous observer semantics).
assign obs_done_id_o = batch_enable_q ? 64'(batch_completed_q) + 1 :
                       ((LaunchPort && launch_ctrl_q && trans_complete) ? launch_id_q :
                        ((&done_id) ? 64'd2 : done_id + 64'd1));

ttype_o                         = dma_reg2hw.conf.ttype.q;
wdata_o                         = dma_reg2hw.wdata.q;

    // Current backend only supports one ID
burst_req_o.opt.axi_id             = AxID;
    // Device ID
burst_req_o.opt.device_id          = DEVICE_ID;
    // Process ID
burst_req_o.opt.pv                 = dma_reg2hw.conf.pv.q;
burst_req_o.opt.process_id         = (dma_reg2hw.conf.pv.q) ?
                                     (PROCESS_ID) :
                                     ('0);
    // DMA only supports incremental burst
burst_req_o.opt.src.burst          = axi_pkg::BURST_INCR;
    // this frontend currently does not support cache variations
burst_req_o.opt.src.cache          = dma_reg2hw.conf.cache.q;
    // AXI4 does not support locked transactions, use atomics
burst_req_o.opt.src.lock           = '0;
    // unpriviledged, secure, data access
burst_req_o.opt.src.prot           = '0;
    // not participating in qos
burst_req_o.opt.src.qos            = '0;
    // only one region
burst_req_o.opt.src.region         = '0;
    // DMA only supports incremental burst
burst_req_o.opt.dst.burst          = axi_pkg::BURST_INCR;
    // this frontend currently does not support cache variations
burst_req_o.opt.dst.cache          = dma_reg2hw.conf.cache.q;
    // AXI4 does not support locked transactions, use atomics
burst_req_o.opt.dst.lock           = '0;
    // unpriviledged, secure, data access
burst_req_o.opt.dst.prot           = '0;
    // not participating in qos
burst_req_o.opt.dst.qos            = '0;
    // only one region in system
burst_req_o.opt.dst.region         = '0;
    // ensure coupled AW to avoid deadlocks
burst_req_o.opt.beo.decouple_aw    = '0;
burst_req_o.opt.beo.decouple_rw    = dma_reg2hw.conf.decouple.q;
    // this frontend currently only supports completely debursting
burst_req_o.opt.beo.src_max_llen   = '0;
    // this frontend currently only supports completely debursting
burst_req_o.opt.beo.dst_max_llen   = '0;
burst_req_o.opt.beo.src_reduce_len = dma_reg2hw.conf.deburst.q;
burst_req_o.opt.beo.dst_reduce_len = dma_reg2hw.conf.deburst.q;

IDLE: begin

    if (LaunchPort && launch_hold_i && launch_next_id_read) begin
        // Controlled preparation: reserve an ID and enter HOLD, or
        // reject (invalid config / simultaneous cancel) without
        // allocating an ID.
        if (launch_cancel_i || !launch_cfg_ok) begin
            dma_ctrl_rsp_o.ready = 1;
            dma_ctrl_rsp_o.error = 1;
        end else begin
            issue               = 1'b1;
            dma_hw2reg.next_id.d = next_id;
            dma_ctrl_rsp_o.ready = 1;
            dma_ctrl_rsp_o.error = 0;
            launch_id_n         = next_id;
            launch_ctrl_n       = 1'b1;
            transf_counter_n    = dma_reg2hw.n_trans.q;
            transf_offset_n     = '0;
            state_n             = HOLD;
        end
    end else if (dma_reg2hw.next_id.re) begin
        if (batch_enable_q && !batch_cfg_ok) begin
            dma_ctrl_rsp_o.ready = 1;
            dma_ctrl_rsp_o.error = 1;
        end else if (dma_reg2hw.num_bytes.q != '0) begin
            issue = 1'b1;
            dma_hw2reg.next_id.d = next_id;
            transf_counter_n = batch_enable_q ? 64'(batch_target_q) : dma_reg2hw.n_trans.q;
            if (batch_enable_q && policy_enable) begin
                // First policy-gated batch copy: reserve the functional ID
                // and wait for backend idle plus allow before offering VALID.
                dma_ctrl_rsp_o.ready = 1'b1;
                transf_offset_n = (batch_enable_q && batch_reverse)
                    ? ((64'(batch_pages_q) - 64'd1) << 12) : '0;
                state_n = ADMIT;
            end else begin
                dma_ctrl_rsp_o.ready = ready_i;
                transf_offset_n = (batch_enable_q && batch_reverse)
                    ? ((64'(batch_pages_q) - 64'd1) << 12) : '0;
                state_n = COUNT;
                if (batch_enable_q && !ready_i) begin
                    issue = 0;
                    state_n = IDLE;
                end
            end
        end

COUNT: begin

    // Send request to FIFO. VALID stays asserted (and addresses stable)
    // regardless of later cancel/hold/go until the backend is ready.
    valid_o              = 1'b1;

    burst_req_o.src_addr = dma_reg2hw.src_addr.q + transf_offset_q;
    burst_req_o.dst_addr = dma_reg2hw.dst_addr.q + transf_offset_q;

    if (ready_i) begin
        state_n          = WAIT;
        transf_counter_n = transf_counter_q - 1;
        if (batch_enable_q && batch_reverse_q) begin
            if (transf_offset_q == 0)
                transf_offset_n = (64'(batch_pages_q) - 64'd1) << 12;
            else
                transf_offset_n = transf_offset_q - 13'h1000;
        end else begin
            transf_offset_n  = transf_offset_q + 13'h1000;
            if (batch_enable_q && transf_offset_n == (64'(batch_pages_q) << 12))
                transf_offset_n = 0;
        end
    end
end

WAIT: begin

    if (trans_complete_i) begin
        if (launch_ctrl_q) begin
            // Controlled job completion.
            trans_complete = 1'b1;
            id_retire      = 1'b1;
            launch_ctrl_n  = 1'b0;
            launch_id_n    = '0;
            state_n        = IDLE;
        end else if ((transf_counter_q == '0) ||
                (!batch_enable_q && dma_reg2hw.conf.ttype.q == idma_pkg::DEFAULT) ||
                (batch_enable_q && (batch_stop_q || policy_abort))) begin
            trans_complete = 1'b1;
            id_retire      = 1'b1;
            state_n = IDLE;
        end else if (batch_enable_q && gap_cycles_q != '0) begin
            // Non-final batch completion: wait before offering the
            // next task.  The first task is never delayed by gap.
            state_n         = GAP;
            gap_countdown_n = gap_cycles_q;

/// - `DEFAULT`: Default read-write behavior
/// - `READ`: Read only. Read data is saved in the rdata register
/// - `WRITE`: Write only. Data to be written must be placed in the wdata register
/// - `PARALLEL`: Read and write performed in parallel
typedef enum logic [1:0] {
    DEFAULT     = 2'b00,
    READ        = 2'b01,
    WRITE       = 2'b10,

/// Determines the maximum number of beats allowed within a burst depending on the protocol
/// - `protocol`: The protocol that is used
function automatic int unsigned determineMaxBeatsPerBurst(protocol_e protocol);
    case (protocol)
    AXI:        return 256;
    // AXI-Lite and OBI do not have bursts
    default:    return 1;
    endcase
endfunction

/// Maximum number of beats within a burst
localparam int unsigned MaxBeatsPerBurst = idma_pkg::determineMaxBeatsPerBurst(Protocol);

/// Stobe width
localparam int unsigned StrbWidth     = DataWidth / 8;
/// Offset width
localparam int unsigned OffsetWidth   = $clog2(StrbWidth);
/// The size of a page in byte
localparam int unsigned PageSize      = (MaxBeatsPerBurst * StrbWidth > 4096) ?
                                        4096 :  MaxBeatsPerBurst * StrbWidth;
/// The width of page offset byte addresses
localparam int unsigned PageAddrWidth = $clog2(PageSize);

assign r_num_bytes_possible = opt_tf_q.decouple_rw ?
                              r_num_bytes_to_pb : c_num_bytes_to_pb;

// max num bytes writable in page
assign w_num_bytes_possible = opt_tf_q.decouple_rw ?
                              w_num_bytes_to_pb : c_num_bytes_to_pb;

if (r_tf_q.length > r_num_bytes_possible) begin
    r_num_bytes = r_num_bytes_possible;
    // calculate remainder
    r_tf_d.length = r_tf_q.length - r_num_bytes_possible;
    // next address
    r_tf_d.addr = r_tf_q.addr + r_num_bytes;

// remaining bytes fit in one burst
end else begin
    r_num_bytes = r_tf_q.length[PageAddrWidth:0];
    // finished
    r_tf_d.valid = 1'b0;
    r_done = 1'b1;
end

//--------------------------------------
// Legalize write transaction
//--------------------------------------
// more bytes remaining than we can write
if (w_tf_q.length > w_num_bytes_possible) begin
    w_num_bytes = w_num_bytes_possible;
    // calculate remainder
    w_tf_d.length = w_tf_q.length - w_num_bytes_possible;
    // next address
    w_tf_d.addr = w_tf_q.addr + w_num_bytes;

// remaining bytes fit in one burst
end else begin
    w_num_bytes = w_tf_q.length[PageAddrWidth:0];
    // finished
    w_tf_d.valid = 1'b0;
    w_done = 1'b1;
end

// new request is taken in if both r and w machines are ready.
if (ready_o & valid_i) begin

    // load all three mutable objects (source, destination, option)
    // source or read
    r_tf_d = '{
        length: req_i.length,
        addr:   req_i.src_addr,
        valid:  is_read
    };
    // destination or write
    w_tf_d = '{
        length: req_i.length,
        addr:   req_i.dst_addr,
        valid:  is_write
    };
    // options
    opt_tf_d = '{
        shift:          req_i.src_addr[OffsetWidth-1:0] - req_i.dst_addr[OffsetWidth-1:0],
        decouple_rw:    req_i.opt.beo.decouple_rw,
        decouple_aw:    req_i.opt.beo.decouple_aw,
        src_max_llen:   req_i.opt.beo.src_max_llen,
        dst_max_llen:   req_i.opt.beo.dst_max_llen,
        src_reduce_len: req_i.opt.beo.src_reduce_len,
        dst_reduce_len: req_i.opt.beo.dst_reduce_len,
        axi_id:         req_i.opt.axi_id,
        device_id:      req_i.opt.device_id,
        pv:             req_i.opt.pv,
        process_id:     req_i.opt.process_id,
        src_axi_opt:    req_i.opt.src,
        dst_axi_opt:    req_i.opt.dst,
        super_last:     req_i.opt.last

// last burst in generic 1D transfer?
assign w_req_o.last = w_done;

// last burst indicated by midend
assign w_req_o.super_last = opt_tf_q.super_last;

// assign aw decouple flag
assign w_req_o.decouple_aw = opt_tf_q.decouple_aw;

// busy output
assign r_busy_o = r_tf_q.valid;
assign w_busy_o = w_tf_q.valid;


//--------------------------------------
// Flow Control
//--------------------------------------
// only advance to next state if:
// * rw_coupled: both machines advance
// * rw_decoupled: either machine advances
always_comb begin : proc_legalizer_flow_control
    if (opt_tf_q.decouple_rw) begin
        r_tf_ena  = (r_ready_i & !flush_i) | kill_i;
        w_tf_ena  = (w_ready_i & !flush_i) | kill_i;

        r_valid_o = r_tf_q.valid & r_ready_i & !flush_i;
        w_valid_o = w_tf_q.valid & w_ready_i & !flush_i;
    end else begin
        r_tf_ena  = (r_ready_i & w_ready_i & !flush_i) | kill_i;
        w_tf_ena  = (r_ready_i & w_ready_i & !flush_i) | kill_i;

        r_valid_o = r_tf_q.valid & w_ready_i & r_ready_i & !flush_i;
        w_valid_o = w_tf_q.valid & r_ready_i & w_ready_i & !flush_i;
    end
end

// load next idma request: if both machines are done!
assign ready_o = r_done & w_done & r_ready_i & w_ready_i & !flush_i;

/// The localparam MetaFifoDepth holds the maximum number of transfers that can be
/// in-flight under any circumstances.
localparam int unsigned MetaFifoDepth = BufferDepth + NumAxInFlight + MemSysDepth;

/// The datapath read request type holds all the information required to configure the read
/// part of the datapath. The type consists of:
/// - `offset`: The bus offset of the read
/// - `trailer`: How many empty bytes are required to pad the transfer to a multiple of the
///              bus width.
/// - `shift`: The amount the data needs to be shifted
/// - `decouple_aw`: If the transfer has the AW decoupled from the R
typedef struct packed {
    offset_t offset;
    offset_t tailer;
    offset_t shift;
    logic    decouple_aw;
} r_dp_req_t;

/// The datapath read response type provides feedback from the read part of the datapath:
/// - `resp`: The response from the R channel of the AXI4 manager interface
/// - `last`: The last flag from the R channel of the AXI4 manager interface
/// - `first`: Is the current item first beat in the burst
typedef struct packed {
    axi_pkg::resp_t resp;
    logic           last;
    logic           first;
} r_dp_rsp_t;

/// The datapath write request type holds all the information required to configure the write
/// part of the datapath. The type consists of:
/// - `offset`: The bus offset of the write
/// - `trailer`: How many empty bytes are required to pad the transfer to a multiple of the
///              bus width.
/// - `num_beats`: The number of beats this burst consist of
/// - `is_single`: Is this transfer just one beat long? `(len == 0)`
typedef struct packed {
    offset_t       offset;
    offset_t       tailer;
    axi_pkg::len_t num_beats;
    logic          is_single;
} w_dp_req_t;

/// The iDMA read request bundles an `AR` type and a datapath read response type together.
typedef struct packed {
    r_dp_req_t    r_dp_req;
    ar_chan_t     ar_req;
} idma_r_req_t;

/// The iDMA write request bundles an `AW` type and a datapath write response type together. It
/// has an additional flags:
/// - `last`: indicating the current burst is the last one of the generic 1D transfer currently
///    being processed
/// - `midend_last`: The current transfer is marked by the controlling as last
/// - `decouple_aw`: indicates this is an R-AW decoupled transfer
typedef struct packed {
    w_dp_req_t    w_dp_req;
    aw_chan_t     aw_req;
    logic         last;
    logic         super_last;
    logic         decouple_aw;
} idma_w_req_t;

typedef struct packed {
    w_dp_req_t    w_dp_req;
    aw_chan_t     aw_req;
} w_aw_dp_req_t;

/// The mutable transfer options type holds important information that is mutated by the
/// `legalizer` block.
typedef struct packed {
    offset_t                shift;
    logic                   decouple_rw;
    logic                   decouple_aw;
    logic [2:0]             src_max_llen;
    logic [2:0]             dst_max_llen;
    logic                   src_reduce_len;
    logic                   dst_reduce_len;
    id_t                    axi_id;
    logic [23:0]            device_id;
    logic                   pv;
    logic [19:0]            process_id;
    idma_pkg::axi_options_t src_axi_opt;
    idma_pkg::axi_options_t dst_axi_opt;
    logic                   super_last;
} idma_mut_tf_opt_t;

/// The mutable transfer type holds important information that is mutated by the
/// `legalizer` block.
typedef struct packed {
    tf_len_t  length;
    addr_t    addr;
    logic     valid;
} idma_mut_tf_t;

// data path, meta channels, and last queues have to be ready for the legalizer to be ready
assign r_ready = r_dp_req_in_ready & ar_ready;
assign w_ready = w_dp_req_in_ready & aw_ready & w_last_ready;

end else if (ErrorCap == idma_pkg::NO_ERROR_HANDLING) begin : gen_no_error_handler
    // bypass the signals, assign their neutral values
    assign idma_rsp.error     = 1'b0;
    assign idma_rsp.pld       = 1'b0;
    assign idma_rsp.last      = w_super_last;
    assign rsp_valid          = (ttype_i == idma_pkg::READ) ? 
                                (r_dp_rsp_valid) : 
                                (w_dp_rsp_valid & w_last_burst);
    assign eh_req_ready_o     = 1'b0;
    assign legalizer_flush    = 1'b0;
    assign legalizer_kill     = 1'b0;
    assign dp_poison          = 1'b0;
    assign r_dp_rsp_ready     = rsp_ready;
    assign w_dp_rsp_ready     = rsp_ready;
    assign busy_o.eh_fsm_busy = 1'b0;
    assign busy_o.eh_cnt_busy = 1'b0;

// Add fall-through register to allow the input to be ready if the output is not. This
// does not add a cycle of delay
fall_through_register #(
    .T          ( ar_chan_t )
) i_ar_fall_through_register (
    .clk_i,
    .rst_ni,
    .testmode_i,
    .clr_i      ( 1'b0         ),
    .valid_i    ( r_valid      ),
    .ready_o    ( ar_ready     ),
    .data_i     ( r_req.ar_req ),
    .valid_o    ( ar_valid_dp  ),
    .ready_i    ( ar_ready_dp  ),
    .data_o     ( ar_req_dp    )
);

// Add fall-through register to allow the input to be ready if the output is not. This
// does not add a cycle of delay
fall_through_register #(
    .T          ( aw_chan_t )
) i_aw_fall_through_register (
    .clk_i,
    .rst_ni,
    .testmode_i,
    .clr_i      ( 1'b0          ),
    .valid_i    ( w_valid       ),
    .ready_o    ( aw_ready      ),
    .data_i     ( w_req.aw_req  ),
    .valid_o    ( aw_valid_dp   ),
    .ready_i    ( aw_ready_dp   ),
    .data_o     ( aw_req_dp     )
);

// connect the ar requests to the AXI bus
assign axi_req_o.ar       = ar_req_i;
assign axi_req_o.ar_valid = ar_valid_i;
assign ar_ready_o         = axi_rsp_i.ar_ready;

assign buffer_in = {axi_rsp_i.r.data, axi_rsp_i.r.data} >> (r_dp_req_i.shift * 8);
assign mask_in   = {read_aligned_in_mask, read_aligned_in_mask}  >> r_dp_req_i.shift;


//--------------------------------------
// Read control
//--------------------------------------
// controls the next state of the read flag
always_comb begin : proc_first_read
    // sticky is first bit for read
    if (!axi_rsp_i.r.last & axi_rsp_i.r_valid & axi_req_o.r_ready) begin
        // new transfer has started
        first_r_d = 1'b0;
    end else if (axi_rsp_i.r.last & axi_rsp_i.r_valid & axi_req_o.r_ready) begin
        // finish read burst
        first_r_d = 1'b1;
    end else begin
        // no change
        first_r_d = first_r_q;
    end
end

// the buffer can be pushed to if all the masked FIFO buffers (mask_in) are ready.
assign in_ready = &(buffer_in_ready | ~mask_in);
// the read can accept data if the buffer is ready and the response channel is ready
assign axi_req_o.r_ready = in_ready & r_dp_ready_i;

// Independent read
logic indep_read;
assign indep_read = (ttype_i != idma_pkg::DEFAULT);

// once valid data is applied, it can be pushed in all the selected (mask_in) buffers
// be sure the response channel is ready
assign in_valid        = axi_rsp_i.r_valid & in_ready & r_dp_ready_i;
assign buffer_in_valid = (in_valid && !indep_read) ? mask_in : '0;

// r_dp_ready_o is triggered by the last element arriving from the read
assign r_dp_ready_o = r_dp_valid_i & r_dp_ready_i &
                      axi_rsp_i.r.last & axi_rsp_i.r_valid & in_ready;

// Send to rdata register
assign rdata_valid_o   = axi_rsp_i.r.last & axi_rsp_i.r_valid & axi_req_o.r_ready;
assign rdata_o         = axi_rsp_i.r.data;

// connect r_dp response payload
assign r_dp_rsp_o.resp  = axi_rsp_i.r.resp;
assign r_dp_rsp_o.last  = axi_rsp_i.r.last;
assign r_dp_rsp_o.first = first_r_q;

// r_dp_valid_o is triggered once the last element is here or an error occurs
assign r_dp_valid_o = axi_rsp_i.r_valid & in_ready & (axi_rsp_i.r.last | (|axi_rsp_i.r.resp));

// all elements needed (defined by the mask) are in the buffer and the buffer is non-empty
assign ready_to_write = ((buffer_out_valid & mask_out) == mask_out) & (buffer_out_valid != '0);

// data needed by the first mask is available in the buffer -> r_first happened for sure
// this signal can be high during a transfer as well, it needs to be masked
assign first_possible = (((buffer_out_valid & w_first_mask) == w_first_mask) &
                         (buffer_out_valid != '0)) | write_q;

// the buffer is completely empty and idle
assign buffer_clean = &(~buffer_out_valid);

// write happening: both the bus (w_ready) and the buffer (ready_to_write) is high
assign write_happening = ready_to_write & axi_rsp_i.w_ready;

// the main buffer is conditionally to the write mask popped
assign buffer_out_ready = write_happening ? mask_out : '0;

// signal the bus that we are ready
assign axi_req_o.w_valid = (ready_to_write | write_q);

        if (ready_to_write == 1'b1 & !dp_poison_i) begin
            // assign data from buffers, mask non valid entries
            for (int i = 0; i < StrbWidth; i++) begin
                buffer_data_masked[i*8 +: 8] = mask_out[i] ? buffer_out[i] : 8'b0;
            end
            // assign the output
            axi_req_o.w.data = buffer_data_masked;
            // assign the out mask to the strobe
            axi_req_o.w.strb = mask_out;
        end
    end

end else begin : gen_direct_connect
    // not used signal
    assign buffer_data_masked = '0;
    // simpler: direct connection
    assign axi_req_o.w.data   = (use_wdata) ? (wdata_i) : (buffer_out);
    assign axi_req_o.w.strb   = dp_poison_i ? '0 : mask_out;
end

// the w last signal should only be applied to the bus if an actual transfer happens
assign axi_req_o.w.last = (last_w & ready_to_write) | write_q;

// we are ready for the next transfer internally, once the w last signal is applied
assign w_dp_ready_o = last_w & (write_happening | write_q);

//--------------------------------------
// Write response
//--------------------------------------
// connect w_dp response payload
assign w_dp_rsp_o.resp = axi_rsp_i.b.resp;
assign w_dp_rsp_o.user = axi_rsp_i.b.user;

// w_dp_valid_o is triggered once the write answer is here
assign w_dp_valid_o = axi_rsp_i.b_valid;

// create back pressure on the b channel if the higher parts of the DMA cannot accept more
// write responses
assign axi_req_o.b_ready = w_dp_ready_i;

idma_buffer #(
    .BufferDepth   ( BufferDepth   ),
    .StrbWidth     ( StrbWidth     ),
    .PrintFifoInfo ( PrintFifoInfo ),
    .strb_t        ( strb_t        ),
    .byte_t        ( byte_t        )
) i_idma_buffer (
    .clk_i,
    .rst_ni,
    .testmode_i,
    .data_i      ( buffer_in        ),
    .valid_i     ( buffer_in_valid  ),
    .ready_o     ( buffer_in_ready  ),
    .data_o      ( buffer_out       ),
    .valid_o     ( buffer_out_valid ),
    .ready_i     ( buffer_out_ready )
);


//--------------------------------------
// Module Control
//--------------------------------------
assign r_dp_busy_o   = r_dp_valid_i | r_dp_ready_o;
assign w_dp_busy_o   = w_dp_valid_i | w_dp_ready_o;
assign buffer_busy_o = !buffer_clean;

// stream fifo
stream_fifo #(
    .DEPTH        ( Depth  ),
    .T            ( type_t ),
    // Full 4 KiB N/S byte lanes use the existing FPGA RAM queue.
    // Small legacy queues and other payload types keep their storage.
    .FORCE_FPGA_RAM ( Depth == 32'd512 && $bits(type_t) == 8 )
) i_stream_fifo (
    .clk_i,
    .rst_ni,
    .flush_i,
    .testmode_i,
    .usage_o,
    .data_i,
    .valid_i,
    .ready_o,
    .data_o,
    .valid_o,
    .ready_i
);

// r/w store dataflow
assign r_store_pop = r_dp_valid_i & r_dp_ready_o & r_dp_rsp_i.last;
assign w_store_pop = w_dp_valid_i & w_dp_ready_o;

// idle state -> error handler is in pass-trough mode until an error occurs
IDLE : begin

    // default: datapath is unblocked
    r_dp_ready_o = rsp_ready_i;
    w_dp_ready_o = rsp_ready_i;

    // a proper write response (lowest priority)
    if (w_dp_rsp_i.resp == axi_pkg::RESP_OKAY & w_dp_valid_i & w_last_burst_i) begin
        rsp_o        =  '0;
        rsp_o.last   = w_super_last_i;
        rsp_valid_o  = 1'b1;
        //rb_out_ready = 1'b1; // pop buffer
    end

    // jump to wait if a write error happens (mid priority)
    if (w_dp_rsp_i.resp != axi_pkg::RESP_OKAY & w_dp_valid_i) begin
        // assemble error package
        rsp_o.error          = 1'b1;
        rsp_o.last           = w_super_last_i;
        rsp_o.pld.cause      = w_dp_rsp_i.resp;
        rsp_o.pld.err_type   = idma_pkg::BUS_WRITE;
        rsp_o.pld.burst_addr = w_addr_head;
        //store_update         = 1'b1;
        rsp_valid_o          = 1'b1;
        // block read datapath response on write error
        r_dp_ready_o         = 1'b0;
        // go to one of the wait states
        if (w_last_burst_i) begin
            state_d              = WAIT_LAST_W;
        end else begin
            state_d              = WAIT;
        end
    end

    // jump to wait if a read error happens (highest priority)
    if (r_dp_rsp_i.resp != axi_pkg::RESP_OKAY & r_dp_valid_i) begin
        // assemble error package
        rsp_o.error          = 1'b1;
        rsp_o.last           = w_super_last_i;
        rsp_o.pld.cause      = r_dp_rsp_i.resp;
        rsp_o.pld.err_type   = idma_pkg::BUS_READ;
        rsp_o.pld.burst_addr = r_addr_head;
        //store_update         = 1'b1;
        rsp_valid_o          = 1'b1;
        // block write datapath response on read error
        w_dp_ready_o         = 1'b0;
        // go to wait state
        state_d              = WAIT;

    parameter bit          FALL_THROUGH = 1'b0,
    /// Default data width if the fifo is of type logic
    parameter int unsigned DATA_WIDTH   = 32,
    /// Depth can be arbitrary from 0 to 2**32
    parameter int unsigned DEPTH        = 8,
    parameter type         T            = logic [DATA_WIDTH-1:0],
    // DO NOT OVERWRITE THIS PARAMETER
    parameter int unsigned ADDR_DEPTH  = (DEPTH > 1) ? $clog2(DEPTH) : 1,
    parameter bit          FORCE_FPGA_RAM = 1'b0
) (
    input  logic                  clk_i,      // Clock
    input  logic                  rst_ni,     // Asynchronous reset active low
    input  logic                  flush_i,    // flush the fifo
    input  logic                  testmode_i, // test_mode to bypass clock gating
    output logic [ADDR_DEPTH-1:0] usage_o,    // fill pointer
    // input interface
    input  T                      data_i,     // data to push into the fifo
    input  logic                  valid_i,    // input data valid
    output logic                  ready_o,    // fifo is not full
    // output interface
    output T                      data_o,     // output data
    output logic                  valid_o,    // fifo is not empty
    input  logic                  ready_i     // pop head from fifo
);

    logic push, pop;
    logic empty, full;

    assign push    = valid_i & ~full;
    assign pop     = ready_i & ~empty;
    assign ready_o = ~full;
    assign valid_o = ~empty;

    fifo_v3 #(
        .FALL_THROUGH   (FALL_THROUGH),
        .DATA_WIDTH     (DATA_WIDTH),
        .DEPTH          (DEPTH),
        .dtype(T),
        .FORCE_FPGA_RAM (FORCE_FPGA_RAM)

localparam int unsigned NumDMADevices = 4;
localparam int unsigned DmaAxiIdWidth =
    ariane_soc::IdWidth - $clog2(NumDMADevices);

for (genvar o = 0; o < NumDMADevices; o++) begin : gen_dma_observation
    assign obs_arvalid[o] = axi_dma_tr_req[o].ar_valid;
    assign obs_awvalid[o] = axi_dma_tr_req[o].aw_valid;
    assign obs_arready[o] = axi_dma_tr_resp[o].ar_ready;
    assign obs_awready[o] = axi_dma_tr_resp[o].aw_ready;
    assign obs_rlast[o] = axi_dma_tr_resp[o].r_valid && axi_dma_tr_resp[o].r.last && axi_dma_tr_req[o].r_ready;
    assign obs_b[o] = axi_dma_tr_resp[o].b_valid && axi_dma_tr_req[o].b_ready;
    // Each current iDMA emits AxID=0. Monitor its private mux-side ID.
    assign obs_bad_id[o] = (obs_arvalid[o] && |axi_dma_tr_req[o].ar.id) ||
        (obs_awvalid[o] && |axi_dma_tr_req[o].aw.id) ||
        (axi_dma_tr_resp[o].r_valid && |axi_dma_tr_resp[o].r.id) ||
        (axi_dma_tr_resp[o].b_valid && |axi_dma_tr_resp[o].b.id);

function automatic rv_iommu_cfg::rv_iommu_cfg_t nonblock_cfg();
    rv_iommu_cfg::rv_iommu_cfg_t cfg = ariane_soc::RVIOMMUCfg;
    if (IOMMUNonblockMode != 0) cfg.MSITrans = rv_iommu_cfg::MSI_BT_ONLY;
