endfunction
initial begin
    if (IOMMUNonblockMode > 3 ||
        (IOMMUNonblockMode != 0 && (IOMMUResearchRole != 0 || IOMMULegacyE3Observer)))
        $fatal(1, "Banked prototype cannot use legacy E3/COST observers");
end
rv_iommu_top #(
    .RVIOMMUCfg   (nonblock_cfg()),
    .BankedEnable(IOMMUNonblockMode != 0),
    .NonblockEnable(IOMMUNonblockMode != 0),
    .PolicyEnable(IOMMUNonblockMode == 3),
    .BankIdBit(DmaAxiIdWidth),

localparam NrSlaves = 4; // actually masters, but slaves on the crossbar

// 4 is recommended by AXI standard, so lets stick to it, do not change
localparam IdWidth   = 4;
localparam IdWidthSlave = IdWidth + $clog2(NrSlaves);

end else begin : gen_prepend
  always_comb begin
    mst_aw_chans_o[i] = slv_aw_chans_i[i];
    mst_ar_chans_o[i] = slv_ar_chans_i[i];
    mst_aw_chans_o[i].id = {pre_id_i, slv_aw_chans_i[i].id[AxiIdWidthSlvPort-1:0]};
    mst_ar_chans_o[i].id = {pre_id_i, slv_ar_chans_i[i].id[AxiIdWidthSlvPort-1:0]};
  end
end
// The ID is in the highest bits of the struct, so an assignment from a channel with a wide ID
// to a channel with a shorter ID correctly cuts the prepended ID.
assign slv_b_chans_o[i] = mst_b_chans_i[i];
assign slv_r_chans_o[i] = mst_r_chans_i[i];

  input logic invalidate_i,
  input ddtp_t ddtp_i,
  output logic intercept_o, accept_o, busy_o,
  output logic ddtc_lookup_o, ddtc_touch_o,
  output device_id_t ddtc_did_o,
  input logic ddtc_hit_i,
  input dc_t ddtc_dc_i,
  output logic iotlb_lookup_o, iotlb_touch_o,
  output logic [GPPNW39-1:0] iotlb_vpn_o,
  output pscid_t iotlb_pscid_o,
  input logic iotlb_hit_i,
  input iotlb_content_t iotlb_content_i,
  output resp_t response_o,
  output logic response_valid_o,
  input logic response_ready_i,
  output logic [15:0] diag_o
);
  typedef enum logic [2:0] {IDLE, DC, LEAF, OUT, REJECT} state_t;
  state_t state_q;
  req_t req_q;
  dc_t dc_q;
  ddtp_t ddtp_q;
  resp_t resp_q;

assign dc_ok = msi_safe && ddtc_hit_i && ddtc_dc_i.tc.v &&
    !ddtc_dc_i.tc.pdtv && !ddtc_dc_i.tc.sxl &&
    !ddtc_dc_i.tc.t2gpa && !ddtc_dc_i.tc.en_ats &&
    !ddtc_dc_i.tc.en_pri && !req_q.pid_valid && !req_q.priv &&
    !req_q.is_debug && (is_write || is_read) && canonical &&
    ddtc_dc_i.fsc.mode == ModeSv39 &&
    ddtc_dc_i.iohgatp.mode == ModeBare &&
    ((ddtp_i.iommu_mode.q == 2 && req_q.did[23:6] == 0) ||
     (ddtp_i.iommu_mode.q == 3 && req_q.did[23:15] == 0) ||
     ddtp_i.iommu_mode.q == 4);
assign leaf_ok = msi_leaf_safe && iotlb_hit_i && iotlb_content_i.content_1S.v &&
    iotlb_content_i.content_1S.u &&
    !iotlb_content_i.content_1S.is_1G &&
    !iotlb_content_i.content_1S.is_2M &&
    (is_write ? iotlb_content_i.content_1S.w :
                iotlb_content_i.content_1S.r);
assign accept_o = state_q == LEAF && enable_i &&
    candidate_valid_i && candidate_i == req_q &&
    !invalidate_i && ddtp_i == ddtp_q && dc_ok &&
    ddtc_dc_i == dc_q && leaf_ok;
// Probes do not change replacement state; only an actually accepted hit
// touches both real caches, exactly once.
assign ddtc_touch_o = accept_o;
assign iotlb_touch_o = accept_o;
assign response_o = resp_q;
assign response_valid_o = state_q == OUT;

assign probe_stable = enable_i && candidate_valid_i && candidate_i == req_q &&
                      !invalidate_i && ddtp_i == ddtp_q;

case (state_q)
  IDLE: if (start) begin
    req_q <= candidate_i;
    ddtp_q <= ddtp_i;
    state_q <= DC;
  end
  DC: begin
    if (!enable_i || invalidate_i || ddtp_i != ddtp_q ||
        !dc_ok || !candidate_valid_i || candidate_i != req_q)
      state_q <= REJECT;
    else begin
      dc_q <= ddtc_dc_i;
      state_q <= LEAF;
    end
  end
  LEAF: begin
    if (accept_o) begin
      resp_q <= '0;
      resp_q.bank <= req_q.bank;
      resp_q.spaddr <= {iotlb_content_i.content_1S.ppn[PPNW-1:0],
                        req_q.iova[11:0]};
      resp_q.r <= iotlb_content_i.content_1S.r;
      resp_q.w <= iotlb_content_i.content_1S.w;
      resp_q.x <= iotlb_content_i.content_1S.x;
      resp_q.u <= iotlb_content_i.content_1S.u;
      resp_q.g <= iotlb_content_i.content_1S.g;
      state_q <= OUT;
    end else state_q <= REJECT;
  end
  OUT: if (response_ready_i) state_q <= IDLE;
  REJECT: if (normal_fire_i || !candidate_valid_i) state_q <= IDLE;
  default: state_q <= IDLE;

// IOTLB
logic                           iotlb_lu;
logic [rv_iommu::GPPNW39-1:0]   iotlb_lu_vpn;
rv_iommu::pscid_t               iotlb_lu_pscid;
rv_iommu::gscid_t               iotlb_lu_gscid;
logic                           iotlb_lu_hit;
rv_iommu::iotlb_content_t       iotlb_lu_content;
rv_iommu::iotlb_up_t            ptw_iotlb_update, msi_iotlb_update;
rv_iommu::iotlb_up_t            iotlb_update;
rv_iommu::research_t            iotlb_research;
assign iotlb_lu         = (state_q == PT) | (state_q == MSI) | n_iotlb_lu;
assign iotlb_lu_vpn     = n_iotlb_lu ? n_iotlb_vpn : req_data.iova[rv_iommu::GPLEN39-1:12];
assign iotlb_lu_pscid   = n_iotlb_lu ? n_iotlb_pscid : pscid_q;
assign iotlb_lu_gscid   = n_iotlb_lu ? '0 : gscid_q;
assign cache_iotlb_en1 = n_iotlb_lu ? 1'b1 : en_1S_q;
assign cache_iotlb_en2 = n_iotlb_lu ? 1'b0 : en_2S_q;
assign iotlb_lu_hit = cache_iotlb_hit && !n_iotlb_lu;
assign iotlb_update     = (msi_iotlb_update.update) ?
                          (msi_iotlb_update) :
                          (ptw_iotlb_update);

// Two lifecycle tags (one outstanding request per bank), one response port.
// A rejected probe never handshakes: the original arbiter later accepts it.
assign normal_gate = !NonblockEnable ||
                     (state_q == IDLE && !req_valid && !n_intercept);
assign trans_req_ready_o = n_intercept ? n_accept : (normal_trans_ready && normal_gate);
assign nonblock_fire_o = n_accept;
assign nonblock_busy_o = n_busy;
// All lifecycle storage must be empty; incoming VALID also excludes a
// same-edge configuration. Never reset or discard a pending response.
assign policy_quiet_o = state_q == IDLE && !req_valid && !arb_req_valid &&
    !trans_req_valid_i && !ats_trans_req_valid_i && !debug_req_valid_i &&
    !ats_ddtc_valid_i && !n_busy && !n_intercept && !n_accept &&
    !fast_resp_valid && !slow_resp_valid && !ats_trans_resp_valid_o &&
    !debug_resp_valid_o && !fault_valid_o && !e3_ptw_active &&
    !ddtw_axi_req_o.ar_valid && !pdtw_axi_req_o.ar_valid &&
    !ptw_axi_req_o.ar_valid && !msiptw_axi_req_o.ar_valid &&
    !ddtw_axi_resp_i.r_valid && !pdtw_axi_resp_i.r_valid &&
    !ptw_axi_resp_i.r_valid && !msiptw_axi_resp_i.r_valid &&
    !iotlb_update.update && !ddtc_update.update &&
    !iotinval_i.inval_vma && !iotinval_i.inval_gvma &&
    !iodirinval_i.inval_ddtc && !iodirinval_i.inval_pdtc;

// IOTLB lookup and PTW Walk
PT: begin

    msi_1S_data_n = msi_1S_content;

    // Signal PT Walk if occurred
    hpm_events_o.valid              = ~iotlb_lu_hit;
    hpm_events_o.etype_msk          = (rv_iommu::hpm_etype_mask_t'(1) << rv_iommu::IOTLB_MISS) |
                                      (rv_iommu::hpm_etype_mask_t'(en_1S_q) << rv_iommu::S1_PTW) |
                                      (rv_iommu::hpm_etype_mask_t'(en_2S_q) << rv_iommu::S2_PTW);
    hpm_events_o.filters.gscid_v    = 1'b1;
    hpm_events_o.filters.pscid_v    = 1'b1;

    /*
      A Page Table Walk may end in:
        (1) Error;
        (2) Successful implicit 2nd-stage translation;
        (3) MSI GPA;
        (4) IOTLB update and hit
    */

    // (1) PTW error
    if (ptw_error) begin
        error_2S_n      = ptw_error_2S;
        error_2S_int_n  = ptw_error_2S_int;
        error_gpaddr_n  = ptw_bad_gpaddr;
        error_code_n    = ptw_cause;
        state_n         = (dc_q.tc.dtf) ?
                            (COMPLETE) :
                            (ERROR);
    end

    // (2) Implicit 2nd-stage translation completed
    if (imp_done) begin
        if (ddt_imp_trans_q) begin
            ddt_imp_trans_n = 1'b0;
            state_n         = DDT;
        end
        else if (pdt_imp_trans_q) begin
            pdt_imp_trans_n = 1'b0;
            state_n         = PDT;
        end
    end

    // (3) GPA is MSI address
    if (gpaddr_is_msi) begin
        state_n = MSI;
    end

    // (4) IOTLB hit
    if (iotlb_lu_hit) begin
        state_n         = COMPLETE;
        is_superpage_n  = iotlb_lu_content.content_1S.is_2M |
                          iotlb_lu_content.content_1S.is_1G |
                          iotlb_lu_content.content_2S.is_2M |
                          iotlb_lu_content.content_2S.is_1G;

        if(en_2S_q && en_2S_q) begin
           x_n = iotlb_lu_content.content_2S.x;
           w_n = iotlb_lu_content.content_2S.w;
           r_n = iotlb_lu_content.content_2S.r;
           g_n = iotlb_lu_content.content_2S.g;
           u_n = iotlb_lu_content.content_2S.u;
        end else if(en_2S_q) begin
           x_n = iotlb_lu_content.content_2S.x;
           w_n = iotlb_lu_content.content_2S.w;
           r_n = iotlb_lu_content.content_2S.r;
           g_n = iotlb_lu_content.content_2S.g;
           u_n = iotlb_lu_content.content_2S.u;
        end else if(en_1S_q) begin
           x_n = iotlb_lu_content.content_1S.x;
           w_n = iotlb_lu_content.content_1S.w;
           r_n = iotlb_lu_content.content_1S.r;
           g_n = iotlb_lu_content.content_1S.g;
           u_n = iotlb_lu_content.content_1S.u;
        end

// Translation completion
COMPLETE: begin

    // Debug translation
    if (req_data.is_debug) begin
        debug_resp_valid_o  = 1'b1;
        if (debug_resp_ready_i) begin
            state_n = IDLE;
        end
    end
    // ATS transltion
    else if(req_data.ttype == rv_iommu::PCIE_ATS_TRANS_REQ) begin
        ats_trans_resp_valid_o  = 1'b1;
        if (ats_trans_resp_ready_i) begin
            state_n = IDLE;
        end
    end
    // Normal translation
    else begin
        slow_resp_valid  = 1'b1;
        if (slow_resp_ready) begin
            state_n = IDLE;
        end
    end

// PTW states
typedef enum logic[1:0] {
  IDLE          = 2'b00,
  MEM_ACCESS    = 2'b01,
  PROC_PTE      = 2'b10,
  ERROR         = 2'b11
} ptw_state_t;
ptw_state_t state_q, state_n;

// PTW walking
assign active_o = (state_q != IDLE);

update_o.pscid = pscid_i;
update_o.gscid = gscid_i;

if(en_2S_i) begin
    update_o.content.content_1S.v    = leaf_1Spte_q.v;
    update_o.content.content_1S.r    = leaf_1Spte_q.r;
    update_o.content.content_1S.w    = leaf_1Spte_q.w;
    update_o.content.content_1S.x    = leaf_1Spte_q.x;
    update_o.content.content_1S.u    = leaf_1Spte_q.u;
    update_o.content.content_1S.g    = leaf_1Spte_q.g | global_mapping_q;
    update_o.content.content_1S.ppn  = leaf_1Spte_q.ppn;
    update_o.content.content_2S.v    = pte.v;
    update_o.content.content_2S.r    = pte.r;
    update_o.content.content_2S.w    = pte.w;
    update_o.content.content_2S.x    = pte.x;
    update_o.content.content_2S.u    = pte.u;
    update_o.content.content_2S.g    = pte.g;
    update_o.content.content_2S.ppn  = pte.ppn;
end

else begin
    update_o.content.content_1S.v    = pte.v;
    update_o.content.content_1S.r    = pte.r;
    update_o.content.content_1S.w    = pte.w;
    update_o.content.content_1S.x    = pte.x;
    update_o.content.content_1S.u    = pte.u;
    update_o.content.content_1S.g    = pte.g | global_mapping_q;
    update_o.content.content_1S.ppn  = pte.ppn;
    update_o.content.content_2S      = '0;

/*** Translation completed ***/

if ((ptw_stage_q == STAGE_2_FINAL) || (!en_2S_i)) begin
        if (!implicit_trans_q)
            update_o.update = 1'b1;
        else
            imp_done_o = 1'b1;
end

// From Spec:
// (1): If i > 0 and pte.vpn[i − 1 : 0] != 0, this is a misaligned superpage.
//      Stop and raise a page-fault exception corresponding to the original access type.
// (2): When a virtual page is accessed and the A bit is clear, or is written and the D bit is clear,
//      a page-fault exception is raised.
// (3): For G-stage address translation, all memory accesses are considered to be user-level accesses,
//      as though executed in U-mode.
if ((main_lvl_q == LVL1 && |pte.ppn[17:0] != 1'b0   ) ||       // 1G
    (main_lvl_q == LVL2 && |pte.ppn[8:0] != 1'b0    ) ||       // 2M
    (!pte.a || !pte.r || (is_store_i && !pte.d)     ) ||
    (ptw_stage_q != STAGE_1 && !pte.u              )) begin

    pf_excep_n          = 1'b1;
    state_n             = ERROR;
    ptw_stage_n         = ptw_stage_q;
    update_o.update     = 1'b0;
    imp_done_o          = 1'b0;

    // Flush
    input  rv_iommu::iotlb_inval_t      inval_i,

    // Experimental replacement allocation only; no lookup/permission change.
    input logic policy_clear_i,
    input logic [RVIOMMUCfg.NumIotlbEntries-1:0] policy_mask_i,

    // Update
    input  rv_iommu::iotlb_up_t         update_i,

    // Lookup
    input  logic                            lookup_i,
    input  logic                            touch_i,
    input  logic [rv_iommu::GPPNW39-1:0]    lu_vpn_i,
    input  rv_iommu::pscid_t                lu_pscid_i,
    input  rv_iommu::gscid_t                lu_gscid_i,
    input  logic                            en_1S_i,
    input  logic                            en_2S_i,
    output logic                            lu_hit_o,
    output rv_iommu::iotlb_content_t        lu_content_o,
    output rv_iommu::research_t            research_o
);

    // Tags
    struct packed {
        logic [10:0]        vpn2;
        logic [8:0]         vpn1;
        logic [8:0]         vpn0;
        rv_iommu::pscid_t   pscid;
        rv_iommu::gscid_t   gscid;
        logic               en_1S;
        logic               en_2S;
        logic               valid;
    } [RVIOMMUCfg.NumIotlbEntries-1:0] tags_q, tags_n;

for (int unsigned i = 0; i < RVIOMMUCfg.NumIotlbEntries; i++) begin

    // PSCID match
    match_pscid[i] = (((lu_pscid_i == tags_q[i].pscid) || content_q[i].content_1S.g) && en_1S_i) || !en_1S_i;

    // GSCID match
    match_gscid[i] = (lu_gscid_i == tags_q[i].gscid && en_2S_i) || !en_2S_i;

    is_1G[i] = rv_iommu::is_trans_1G(   en_1S_i,
                                        en_2S_i,
                                        content_q[i].content_1S.is_1G,
                                        content_q[i].content_2S.is_1G
                                    );

    is_2M[i] = rv_iommu::is_trans_2M(   en_1S_i,
                                        en_2S_i,
                                        content_q[i].content_1S.is_1G,
                                        content_q[i].content_1S.is_2M,
                                        content_q[i].content_2S.is_1G,
                                        content_q[i].content_2S.is_2M
                                    );

    // Stage match
    match_stage[i] = (tags_q[i].en_2S == en_2S_i) && (tags_q[i].en_1S == en_1S_i);

    // Full match
    if (tags_q[i].valid && match_pscid[i] && match_gscid[i] && match_stage[i] && (vpn2 == tags_q[i].vpn2)) begin

        // 1G match | 2M match | 4k match
        if (is_1G[i] || ((vpn1 == tags_q[i].vpn1) && (is_2M[i] || vpn0 == tags_q[i].vpn0))) begin
            lu_content_o    = content_q[i];
            lu_hit_o        = 1'b1;
            lu_hit[i]       = 1'b1;
        end

else if(inval_i.inval_gvma) begin
    unique case ({inval_i.gv, inval_i.av})
        2'b00, 2'b01: begin
            // 2S enabled, 1S don't care
            if(tags_q[i].en_2S) begin
                tags_n[i].valid = 1'b0;
            end
        end
        2'b10: begin
            // 2S enabled, 1S don't care, GSCID match
            if(tags_q[i].en_2S && tags_q[i].gscid == inval_i.gscid) begin
                tags_n[i].valid = 1'b0;
            end
        end
        2'b11: begin
            // 2S enabled, 1S don't care, GSCID match, IOVA match
            if(tags_q[i].en_2S && tags_q[i].gscid == inval_i.gscid && 
               (gpaddr_4k_match[i] || gpaddr_2M_match[i] || gpaddr_1G_match[i])) begin
                tags_n[i].valid = 1'b0;
            end
        end
    endcase
end

// update
else if (update_i.update && replace_en[i]) begin

    tags_n[i] = '{
        pscid:      update_i.pscid,
        gscid:      update_i.gscid,
        vpn2:       update_i.vpn[rv_iommu::GPPNW39-1:18],
        vpn1:       update_i.vpn[17:9],
        vpn0:       update_i.vpn[8:0],
        en_1S:      en_1S_i,
        en_2S:      en_2S_i,
        valid:      1'b1
    };

    content_n[i] = update_i.content;

typedef logic [$clog2(RVIOMMUCfg.NumOutstandingTrans):0] w_cnt_t;
w_cnt_t w_cnt_q;
logic incr_w_cnt;
logic decr_w_cnt;
assign incr_w_cnt = (axi_comp_req.aw_valid & axi_comp_resp.aw_ready);
assign decr_w_cnt = (w_valid & w_ready & w_data.last);

always_comb begin : completion_bus

    /* Request */
    axi_comp_req.aw.id      = aw_data.id;
    axi_comp_req.aw.addr    = addr_t'(trans_resp_data_q.spaddr);
    axi_comp_req.aw.len     = aw_data.len;
    axi_comp_req.aw.size    = aw_data.size;
    axi_comp_req.aw.burst   = aw_data.burst;
    axi_comp_req.aw.lock    = aw_data.lock;
    axi_comp_req.aw.cache   = aw_data.cache;
    axi_comp_req.aw.prot    = aw_data.prot;
    axi_comp_req.aw.qos     = aw_data.qos;
    axi_comp_req.aw.region  = aw_data.region;
    axi_comp_req.aw.atop    = aw_data.atop;
    axi_comp_req.aw.user    = aw_data.user;
    axi_comp_req.aw_valid   = complete_write;

    axi_comp_req.ar.id      = ar_data.id;
    axi_comp_req.ar.addr    = addr_t'(trans_resp_data_q.spaddr);
    axi_comp_req.ar.len     = ar_data.len;
    axi_comp_req.ar.size    = ar_data.size;
    axi_comp_req.ar.burst   = ar_data.burst;
    axi_comp_req.ar.lock    = ar_data.lock;
    axi_comp_req.ar.cache   = ar_data.cache;
    axi_comp_req.ar.prot    = ar_data.prot;
    axi_comp_req.ar.qos     = ar_data.qos;
    axi_comp_req.ar.region  = ar_data.region;
    axi_comp_req.ar.user    = ar_data.user;
    axi_comp_req.ar_valid   = complete_read;

    axi_comp_req.w          = w_data;
    axi_comp_req.w_valid    = w_valid & (w_cnt_q != '0);
    axi_comp_req.r_ready    = tr_axi_req_i.r_ready;
    axi_comp_req.b_ready    = tr_axi_req_i.b_ready;

    /* Response */
    tr_axi_resp_o           = axi_comp_resp;
    tr_axi_resp_o.aw_ready  = tr_aw_ready;
    tr_axi_resp_o.ar_ready  = tr_ar_ready;
    tr_axi_resp_o.w_ready   = tr_w_ready;

// Forward AW before AR so read-to-write DMA can open the W drain
// before source read data fills the write-data FIFO.
IDLE: begin
    // Write request received
    // Stall writes if W FIFO is full
    if (aw_valid && !w_cnt_ovf) begin

        // Tags
        trans_req_data_n.iova       = aw_data.addr;
        trans_req_data_n.did        = aw_data.stream_id;
        trans_req_data_n.pid_valid  = aw_data.ss_id_valid;
        trans_req_data_n.pid        = aw_data.substream_id;
        trans_req_data_n.ttype      = aw_data.mmu_atst && !aw_data.mmu_valid ?
                                      rv_iommu::TRANSLATED_W :
                                      rv_iommu::UNTRANSLATED_W;
        // AxPROT[0] indicates privileged transaction when set
        trans_req_data_n.priv       = aw_data.prot[0];
        trans_req_data_n.is_debug   = 1'b0;

        state_n = REQ_TRANS;
    end

    // Read request received
    else if (ar_valid && (!ReadAdmissionEnable || read_admit_i ||
             (fullbuffer_job_i && ar_data.stream_id == FullBufferDID))) begin
        // Tags
        trans_req_data_n.iova       = ar_data.addr;
        trans_req_data_n.did        = ar_data.stream_id;
        trans_req_data_n.pid_valid  = ar_data.ss_id_valid;
        trans_req_data_n.pid        = ar_data.substream_id;
        if(ar_data.mmu_atst && !ar_data.mmu_valid) begin
           // ARPROT[2] indicates data access (r) when LOW, instruction access (rx) when HIGH
           trans_req_data_n.ttype   = (ar_data.prot[2]) ?
                                      (rv_iommu::TRANSLATED_RX) :
                                      (rv_iommu::TRANSLATED_R);
        end else begin
           // ARPROT[2] indicates data access (r) when LOW, instruction access (rx) when HIGH
           trans_req_data_n.ttype   = (ar_data.prot[2]) ?
                                      (rv_iommu::UNTRANSLATED_RX) :
                                      (rv_iommu::UNTRANSLATED_R);
        end
        // AxPROT[0] indicates privileged transaction when set
        trans_req_data_n.priv       = ar_data.prot[0];
        trans_req_data_n.is_debug   = 1'b0;

        state_n = REQ_TRANS;
    end

REQ_TRANS: begin

    if (check_valid) begin

        trans_req_valid_o = 1'b1;

        if (trans_req_ready_i) begin
            state_n     = AWAIT_RESP;
        end
    end

    // Boundary violation
    else begin
        state_n = COMPLETE;
        trans_resp_data_n.error = 1'b1;
    end
end

// Await for a translation response
AWAIT_RESP: begin

    trans_resp_ready_o = 1'b1;

    // Translation finished
    if (trans_resp_valid_i) begin
        trans_resp_data_n   = trans_resp_data_i;
        state_n             = (trans_resp_data_i.is_mrif &&
                               !trans_resp_data_i.error) ? (MRIF) : (COMPLETE);
    end
end

// Trigger MRIF Handler
MRIF: begin

    mrif_req_valid_d = 1'b1;
    if (mrif_req_ready_q) begin
        state_n = COMPLETE;
    end
end

// Complete transaction
// Select slave
COMPLETE: begin

    complete_read = is_read;
    complete_write = is_write;

    if ((axi_comp_resp.ar_ready && is_read) ||
        (axi_comp_resp.aw_ready && is_write)) begin
        aw_ready    = is_write;
        ar_ready    = is_read;
        state_n     = IDLE;

// Per-bank configuration: NumOutstandingTrans and WFifoDepth are SPLIT,
// everything else (caches, fault/MRIF FIFOs, widths, ...) is unchanged.
// MSITrans is preserved (no MRIF); InclATS is forced low.
//=========================================================================
localparam rv_iommu_cfg::rv_iommu_cfg_t RVIOMMUCfgBank = rv_iommu_cfg::rv_iommu_cfg_t'{
    NumOutstandingTrans : RVIOMMUCfg.NumOutstandingTrans / 2,
    WFifoDepth          : RVIOMMUCfg.WFifoDepth / 2,
    MrifFifoDepth       : RVIOMMUCfg.MrifFifoDepth,
    FaultFifoDepth      : RVIOMMUCfg.FaultFifoDepth,
    NumIotlbEntries     : RVIOMMUCfg.NumIotlbEntries,
    NumDdtcEntries      : RVIOMMUCfg.NumDdtcEntries,
    NumPdtcEntries      : RVIOMMUCfg.NumPdtcEntries,

// The input demux keeps W ownership until LAST. A source read from the
// other bank can otherwise fill its DMA's small R->W FIFO while its AW
// cannot enter that demux. The shared memory R channel then cannot return
// the current owner's source data or page-table reads: a circular wait.
// Delay SELECTING such reads, rather than withdrawing an AXI/TL VALID.
// Writes and already-selected transactions retain their original protocol.
// A visible new AW also reserves admission before its input handshake.
// W may legally finish before a stalled AW is accepted, hence the signed
// balance (minimum -1 for that reserved head), rather than an unsigned
// AW-minus-LAST counter that could underflow.
logic signed [31:0] w_unfilled_q;
logic w_owner_q, read_owner, restrict_reads;
logic [1:0] bank_read_admit;
assign restrict_reads = (w_unfilled_q > 0) || tr_axi_req_i.aw_valid;
assign read_owner = (w_unfilled_q > 0) ? w_owner_q : aw_sel;
// If a new AW enters this bank on this edge, its FIFO head only becomes
// visible on the next cycle. Do not select an older queued AR one cycle
// ahead of that AW. When the AW FIFO is full (no AW handshake), allow the
// current owner to read and drain already-prepared writes instead.
assign bank_read_admit[0] = ((w_unfilled_q > 0) ? !read_owner : !restrict_reads)
                            && !(aw_accept && !aw_sel);
assign bank_read_admit[1] = ((w_unfilled_q > 0) ?  read_owner : !restrict_reads)
                            && !(aw_accept &&  aw_sel);

//   Aggregates, over both banks:
//     * AW accepted at the upstream input until the upstream B handshake
//       (covers the whole write, including completion AW/AR accepted by the
//       output and held downstream, i.e. "accepted output pressure")
//     * AR accepted until the upstream R-LAST handshake
//     * W-LAST bursts accepted at the upstream input until the upstream B
//       handshake.  A write is counted by its LAST beat and is NOT tracked
//       by downstream forwarding: a write rejected by a bank (translation
//       error) is consumed internally by that bank's error slave and
//       answered with an upstream B, but it is NEVER forwarded to the
//       completion port.  A forward-based W counter would therefore never
//       decrement for those beats and in_flight_o would stay stuck high
//       forever (phantom non-quiet).
//     * w_partial_q: set when a W burst has started (a non-LAST beat was
//       accepted upstream) and cleared when its LAST beat is accepted;
//       covers the window between the first beat of a burst and its LAST.
//     * both bank controller states (bank in_flight_o = state != IDLE)
//   32-bit counters, asserted bounded / no underflow.  Increment and
//   decrement on the same cycle are netted, so they can never produce a
//   false underflow or a spurious overflow report.
//=========================================================================
logic aw_accept, ar_accept, w_accept, w_nonlast_accept, w_last_accept,
      b_return, r_last_return;

assign aw_accept        = tr_axi_req_i.aw_valid && tr_axi_resp_o.aw_ready;
assign ar_accept        = tr_axi_req_i.ar_valid && tr_axi_resp_o.ar_ready;
assign w_accept         = tr_axi_req_i.w_valid  && tr_axi_resp_o.w_ready;
assign w_nonlast_accept = w_accept && !tr_axi_req_i.w.last;
assign w_last_accept    = w_accept &&  tr_axi_req_i.w.last;
assign b_return         = tr_axi_resp_o.b_valid && tr_axi_req_i.b_ready;
assign r_last_return    = tr_axi_resp_o.r_valid && tr_axi_req_i.r_ready && tr_axi_resp_o.r.last;

logic [31:0] inflight_aw_q, inflight_ar_q, inflight_w_q;
logic        w_partial_q;

always_ff @(posedge clk_i or negedge rst_ni) begin : inflight_counters
    if (!rst_ni) begin
        inflight_aw_q <= 32'd0;
        inflight_ar_q <= 32'd0;
        inflight_w_q  <= 32'd0;
        w_partial_q   <= 1'b0;
    end else begin
        inflight_aw_q <= inflight_aw_q
                       + (aw_accept     ? 32'd1 : 32'd0)
                       - (b_return      ? 32'd1 : 32'd0);
        inflight_ar_q <= inflight_ar_q
                       + (ar_accept     ? 32'd1 : 32'd0)
                       - (r_last_return ? 32'd1 : 32'd0);
        inflight_w_q  <= inflight_w_q
                       + (w_last_accept ? 32'd1 : 32'd0)
                       - (b_return      ? 32'd1 : 32'd0);
        w_partial_q   <= w_last_accept    ? 1'b0 :
                         w_nonlast_accept ? 1'b1 :
                         w_partial_q;
    end
end

assign in_flight_o = (inflight_aw_q != 32'd0) ||
                     (inflight_ar_q != 32'd0) ||
                     (inflight_w_q  != 32'd0) ||
                     w_partial_q ||
                     bank_busy[0] || bank_busy[1];

) i_rv_iommu_regmap (
    .clk_i          (clk_i),
    .rst_ni         (rst_ni),

    .reg_req_i      (regmap_req_i),
    .reg_rsp_o      (regmap_resp_o),

    .reg2hw_o       (reg2hw),
    .hw2reg_i       (hw2reg),

    .devmode_i      (1'b0),
    .in_flight_i    (in_flight_i)
);

//-----------------------
// Command Queue Handler
//-----------------------
rv_iommu_cq_handler #(
    .RVIOMMUCfg          (RVIOMMUCfg),

    .addr_t              (addr_t),
    .paddr_t             (paddr_t),

    .axi_req_t           (axi_req_t),
    .axi_resp_t          (axi_resp_t)
) i_rv_iommu_cq_handler (
    .clk_i               (clk_i),

FETCH: begin
    mem_req_o.ar_valid = 1'b1;
    if (mem_resp_i.ar_ready) begin
        state_n     = REGISTER;
    end
end

REGISTER: begin
    if (mem_resp_i.r_valid) begin
        mem_req_o.r_ready   = 1'b1;
        if (mem_resp_i.r.last) begin
            cmd_n[127:64]   = mem_resp_i.r.data[((64*1) &
                                    (RVIOMMUCfg.AxiDataWidth-1))+:64];
            cq_head_o       = (cq_head_i + 1) & idx_mask;
            state_n         = DECODE;
        end
        else cmd_n[63:0]    = mem_resp_i.r.data[((64*0) &
                                    (RVIOMMUCfg.AxiDataWidth-1))+:64];

        // Check for AXI transmission errors
        if (mem_resp_i.r.resp != axi_pkg::RESP_OKAY) begin
            state_n         = ERROR;
            cqcsr_mf_o      = 1'b1;
            cqcsr_mf_wen_o  = 1'b1;
        end
    end

rv_iommu::IOTINVAL: begin

    iotinval_o.av       = cmd_iotinval.av;
    iotinval_o.gv       = cmd_iotinval.gv;
    iotinval_o.pscv     = cmd_iotinval.pscv;
    iotinval_o.vpn      = cmd_iotinval.addr[(rv_iommu::GPPNW39-1):0];
    iotinval_o.gscid    = cmd_iotinval.gscid;
    iotinval_o.pscid    = cmd_iotinval.pscid;

    // From Spec:
    // A command is determined to be illegal if a reserved bit is set to 1
    // Setting PSCV to 1 with IOTINVAL.GVMA is illegal
    if ((|cmd_iotinval.reserved_1) || (|cmd_iotinval.reserved_2)                        ||
        (|cmd_iotinval.reserved_3) || (|cmd_iotinval.reserved_4)                        ||
        (cmd_iotinval.func3 != rv_iommu::VMA && cmd_iotinval.func3 != rv_iommu::GVMA)   ||
        (cmd_iotinval.func3 == rv_iommu::GVMA && cmd_iotinval.pscv)) begin

        cqcsr_ill_o     = 1'b1;
        cqcsr_ill_wen_o = 1'b1;
        state_n         = ERROR;
    end

    // Check func3 to determine if command is VMA or GVMA
    else if (cmd_iotinval.func3 == rv_iommu::VMA) begin
        iotinval_o.inval_vma    = 1'b1;
    end

    else if (cmd_iotinval.func3 == rv_iommu::GVMA) begin
        iotinval_o.inval_gvma   = 1'b1;
    end

/*
    A IOFENCE.C command completion, as determined by cqh advancing past the index of the IOFENCE.C
    command in the CQ, guarantees that all previous commands fetched from the CQ have been
    completed and committed.
*/
rv_iommu::IOFENCE: begin

    // From Spec:
    // A command is determined to be illegal if a reserved bit is set to 1
    if ((|cmd_iofence.reserved_1) || (|cmd_iofence.reserved_2)  ||
        (cmd_iofence.func3 != rv_iommu::IOFENCE_C)) begin
        cqcsr_ill_o     = 1'b1;
        cqcsr_ill_wen_o = 1'b1;
        state_n         = ERROR;
    end

    // Valid IOFENCE.C command
    else begin

        // TODO: Add IOFENCE support with PR and PW using R/W counters

        // From Spec:
        // If AV=1, the IOMMU writes DATA to memory at a 4-byte aligned address ADDR[63:2] * 4
        if(cmd_iofence.av) begin
            cq_pptr_n   = {cmd_iofence.addr[PLEN-1-2:0], 2'b0};
            wr_state_n  = AW_REQ;
            state_n     = WRITE;
        end

        // Set cqcsr.fence_w_ip if IOMMU supports and uses WSIs
        if (cmd_iofence.wsi && wsi_en_i) begin
            cqcsr_fence_o       = 1'b1;
            cqcsr_fence_wen_o   = 1'b1;
        end

        // Wait for ATS invalidations to complete before proceeding.
        if(atsinval_inflight_i) begin
           ats_fence_valid_o = 1'b1;
           // The ATS synch request has completed.
           if(ats_fence_ready_i) begin
              state_n = IDLE;
           // An Invalidation timed out.
           end else if(atsinval_to_i) begin
              cqcsr_to_o = 1'b1;
              cqcsr_to_wen_o = 1'b1;
           // Wait for invalidations to complete.
           end else begin
              state_n = DECODE;
           end
        end

    end

// There is pending data to be written to ddtp
if ((write_h_q || write_l_q)) begin

  // Write data if there is no in-flight transaction
  if (!in_flight_i) begin
    if (write_l_q) begin
      write_l_n           = 1'b0;
      ddtp_iommu_mode_we  = 1'b1;
      ddtp_ppn_l_we       = 1'b1;
    end

    if (write_h_q) begin
      write_h_n           = 1'b0;
      ddtp_ppn_h_we       = 1'b1;
    end

    // Clear busy bit
    ddtp_busy_de      = 1'b1;
  end
end

// There is no pending data to be written to ddtp
else begin

  // SW is trying to write to the low half of ddtp
  if (ddtp_l_we) begin

    // Check whether the IOMMU has in-flight transactions
    if (in_flight_i) begin
      // Wait for all in-flight transactions to finish
      write_l_n         = 1'b1;
      // Set busy bit
      ddtp_busy_de      = 1'b1;
      ddtp_busy_d       = 1'b1;
      // Save input values
      ddtp_iommu_mode_n = reg_wdata[3:0];
      ddtp_ppn_l_n      = reg_wdata[31:10];

static int idma_iommu_map_range(struct iommu_domain *domain,
				unsigned long iova, phys_addr_t phys,
				size_t size, size_t pgsize)
{
	size_t off;
	int ret;

	for (off = 0; off < size; off += pgsize) {
		ret = iommu_map(domain, iova + off, phys + off, pgsize,
				IOMMU_READ | IOMMU_WRITE, GFP_KERNEL);
		if (ret) {
			while (off) {
				off -= pgsize;
				iommu_unmap(domain, iova + off, pgsize);
			}
			return ret;
		}
	}

	return 0;
}

