static int idma_stream_prepare(struct idma_stream *s, struct idma_device *idma,
			       u32 pages, u32 chunk,
			       struct idma_experiment_stats *stats)
{
	struct page *src_page, *dst_page;
	size_t i;
	int ret;

	s->idma = idma;
	s->dev = idma->miscdev.parent;
	s->stats = stats;
	s->domain = iommu_get_domain_for_dev(s->dev);
	if (!s->domain || s->domain->type == IOMMU_DOMAIN_IDENTITY)
		return -EOPNOTSUPP;
	s->size = (size_t)pages * PAGE_SIZE;
	s->chunk = chunk;
	s->src = dma_alloc_attrs(s->dev, s->size, &s->src_dma, GFP_KERNEL,
				 DMA_ATTR_FORCE_CONTIGUOUS);
	if (!s->src)
		return -ENOMEM;
	s->dst = dma_alloc_attrs(s->dev, s->size, &s->dst_dma, GFP_KERNEL,
				 DMA_ATTR_FORCE_CONTIGUOUS);
	if (!s->dst)
		return -ENOMEM;
	for (i = 0; i < s->size / sizeof(u64); i++) {
		((u64 *)s->src)[i] = idma_pattern(s, i);
		((u64 *)s->dst)[i] = ~idma_pattern(s, i);
	}
	src_page = idma_buffer_page(s->src);
	dst_page = idma_buffer_page(s->dst);
	if (!src_page || !dst_page)
		return -EFAULT;
	ret = idma_find_iova(s->domain, s->size, &s->src_iova, &s->dst_iova);
	if (ret)
		return ret;
	ret = idma_iommu_map_range(s->domain, s->src_iova,
				   page_to_phys(src_page), s->size, PAGE_SIZE);
	if (ret)
		return ret;
	s->mapped_src = true;
	ret = idma_iommu_map_range(s->domain, s->dst_iova,
				   page_to_phys(dst_page), s->size, PAGE_SIZE);
	if (ret)
		return ret;
	s->mapped_dst = true;
	return 0;
}

static void idma_quarantine(struct idma_stream *s)
{
	s->retain = true;
	WRITE_ONCE(s->idma->quarantined, true);
	if (s->stats)
		s->stats->quarantined = 1;
	dev_crit(s->dev, "experiment DMA not safely drained; buffers retained until reboot\n");

u64 done;

if (!s->in_flight)
	return 0;
done = readq(s->idma->reg + IDMA_DONE_REG_OFFSET);
if (done != s->transfer_id)
	return ktime_get_ns() > s->deadline_ns ? -ETIMEDOUT : 0;
s->last_complete_ns = ktime_get_ns();
if (s->diagnostic && !s->batch_started)
	s->diagnostic->warm_completed++;
s->in_flight = false;
if (!s->batch_configured)
	s->touched_end = max(s->touched_end, s->offset + s->chunk);
if (measured) {
	s->stats->completed++;
	s->stats->completed_bytes += s->chunk;
}
return 1;

u64 done;
int ret;

if (!s->in_flight)
	return s->retain ? -EIO : 0;
ret = readq_poll_timeout(s->idma->reg + IDMA_DONE_REG_OFFSET, done,
			 done == s->transfer_id, 0, IDMA_XFER_TIMEOUT_US);
if (ret) {
	idma_quarantine(s);
	return ret;
}
s->in_flight = false;
if (s->diagnostic && !s->batch_started)
	s->diagnostic->warm_drained++;
if (!s->batch_configured)
	s->touched_end = max(s->touched_end, s->offset + s->chunk);
return 0;

/*
 * On this CVA6, FENCE.I also invalidates the WT data cache.
 * Probe only after failure and safe drain; preserve the failure.
 * This is not a generic DMA cache-coherency fix.
 */
local_flush_icache_all();
src_after = READ_ONCE(((u8 *)s->src)[i]);
dst_after = READ_ONCE(((u8 *)s->dst)[i]);

/*
 * Platform workaround: this CVA6 has no DMA snoop of the WT data cache.
 * Its FENCE.I drains CPU writes and invalidates D-cache as well as I-cache.
 * Hand initialized buffers to DMA before warmup; never flush per transfer.
 */
local_flush_icache_all();

static inline void riscv_iommu_cmd_inval_vma(struct riscv_iommu_command *cmd)
{
	cmd->dword0 =
	    FIELD_PREP(RISCV_IOMMU_CMD_OPCODE,
		       RISCV_IOMMU_CMD_IOTINVAL_OPCODE) | FIELD_PREP(RISCV_IOMMU_CMD_FUNC,
								     RISCV_IOMMU_CMD_IOTINVAL_FUNC_VMA);
	cmd->dword1 = 0;
}

static void riscv_iommu_cmd_inval_gvma(struct riscv_iommu_command *cmd)
{
	cmd->dword0 =
	    FIELD_PREP(RISCV_IOMMU_CMD_OPCODE,
		       RISCV_IOMMU_CMD_IOTINVAL_OPCODE) | FIELD_PREP(RISCV_IOMMU_CMD_FUNC,
								     RISCV_IOMMU_CMD_IOTINVAL_FUNC_GVMA);
	cmd->dword1 = 0;
}

static inline void riscv_iommu_cmd_inval_set_addr(struct riscv_iommu_command *cmd,
						  u64 addr)
{
	cmd->dword0 |= RISCV_IOMMU_CMD_IOTINVAL_AV;
	cmd->dword1 = addr;
}

static inline void riscv_iommu_cmd_inval_set_pscid(struct riscv_iommu_command *cmd,
						   unsigned pscid)
{
	cmd->dword0 |= FIELD_PREP(RISCV_IOMMU_CMD_IOTINVAL_PSCID, pscid) |
	    RISCV_IOMMU_CMD_IOTINVAL_PSCV;
}

static inline void riscv_iommu_cmd_inval_set_gscid(struct riscv_iommu_command *cmd,
						   unsigned gscid)
{
	cmd->dword0 |= FIELD_PREP(RISCV_IOMMU_CMD_IOTINVAL_GSCID, gscid) |
	    RISCV_IOMMU_CMD_IOTINVAL_GV;
}

static inline void riscv_iommu_cmd_iofence(struct riscv_iommu_command *cmd)
{
	cmd->dword0 = FIELD_PREP(RISCV_IOMMU_CMD_OPCODE, RISCV_IOMMU_CMD_IOFENCE_OPCODE) |
	    FIELD_PREP(RISCV_IOMMU_CMD_FUNC, RISCV_IOMMU_CMD_IOFENCE_FUNC_C);
	cmd->dword1 = 0;
}

static inline void riscv_iommu_cmd_iofence_set_av(struct riscv_iommu_command *cmd,
						  u64 addr, u32 data)
{
	cmd->dword0 = FIELD_PREP(RISCV_IOMMU_CMD_OPCODE, RISCV_IOMMU_CMD_IOFENCE_OPCODE) |
	    FIELD_PREP(RISCV_IOMMU_CMD_FUNC, RISCV_IOMMU_CMD_IOFENCE_FUNC_C) |
	    FIELD_PREP(RISCV_IOMMU_CMD_IOFENCE_DATA, data) | RISCV_IOMMU_CMD_IOFENCE_AV;
	cmd->dword1 = (addr >> 2);

next = (last + 1) & (iommu->cmdq.cnt - 1);
if (next != head) {
	struct riscv_iommu_command *ptr = iommu->cmdq.base;
	ptr[last] = *cmd;
	wmb();
	riscv_iommu_writel(iommu, RISCV_IOMMU_REG_CQT, next);
	iommu->cmdq.lui = next;
}

spin_unlock_irqrestore(&iommu->cq_lock, flags);

if (sync && head != next) {
	cycles_t start_time = get_cycles();
	while (1) {
		last = riscv_iommu_readl(iommu, RISCV_IOMMU_REG_CQH) &
		    (iommu->cmdq.cnt - 1);
		if (head < next && last >= next)
			break;
		if (head > next && last < head && last >= next)
			break;
		if (RISCV_IOMMU_TIMEOUT < (get_cycles() - start_time)) {
			dev_err(iommu->dev, "IOFENCE TIMEOUT\n");
			return false;
		}
		cpu_relax();
	}

static bool riscv_iommu_iofence_sync(struct riscv_iommu_device *iommu)
{
	struct riscv_iommu_command cmd;
	riscv_iommu_cmd_iofence(&cmd);
	return riscv_iommu_post_sync(iommu, &cmd, true);
}

static void riscv_iommu_flush_iotlb_range(struct iommu_domain *iommu_domain,
					  unsigned long *start, unsigned long *end,
					  size_t *pgsize)
{
	struct riscv_iommu_domain *domain = iommu_domain_to_riscv(iommu_domain);
	struct riscv_iommu_command cmd;
	struct riscv_iommu_endpoint *endpoint;
	// unsigned long iova;
	unsigned long payload;

	if (domain->mode == RISCV_IOMMU_DC_FSC_MODE_BARE)
		return;

	/* Domain not attached to an IOMMU! */
	BUG_ON(!domain->iommu);

	if (start && end) {
		payload = riscv_iommu_ats_inval_payload(*start, *end, true);
	} else {
		payload = riscv_iommu_ats_inval_all_payload(true);
	}

	if (domain->g_stage) {
		riscv_iommu_cmd_inval_gvma(&cmd);
		riscv_iommu_cmd_inval_set_gscid(&cmd, domain->id);
	} else {
		riscv_iommu_cmd_inval_vma(&cmd);
		// riscv_iommu_cmd_inval_set_pscid(&cmd, domain->id);
	}

	// if (start && end && pgsize) {
	// 	/* Cover only the range that is needed */
	// 	for (iova = *start; iova <= *end; iova += *pgsize) {
	// 		printk("Sending IOTINVAL with ADDR");
	// 		riscv_iommu_cmd_inval_set_addr(&cmd, iova);
	// 		riscv_iommu_post(domain->iommu, &cmd);
	// 	}
	// } else {
		riscv_iommu_post(domain->iommu, &cmd);
	// }
	riscv_iommu_iofence_sync(domain->iommu);

	/* ATS invalidation for every device and for every translation */
	list_for_each_entry(endpoint, &domain->endpoints, domains) {
		if (!endpoint->pasid_enabled)
			continue;

		riscv_iommu_cmd_ats_inval(&cmd);
		riscv_iommu_cmd_ats_set_dseg(&cmd, endpoint->domid);
		riscv_iommu_cmd_ats_set_rid(&cmd, endpoint->devid);
		riscv_iommu_cmd_ats_set_pid(&cmd, domain->pscid);
		riscv_iommu_cmd_ats_set_payload(&cmd, payload);
		riscv_iommu_post(domain->iommu, &cmd);
	}
	riscv_iommu_iofence_sync(domain->iommu);

/* IOTINVAL.VMA with GV, AV and PSCV clear: every host S1 entry. */
riscv_iommu_cmd_inval_vma(&cmd);
if (!riscv_iommu_post(iommu, &cmd)) {
	ret = -EIO;
	goto unlock;
}
if (!riscv_iommu_iofence_sync(iommu)) {
	ret = -EIO;
	goto unlock;

